  "content": "import { useState, useEffect } from 'react';
import { Line } from 'react-chartjs-2';
import { Chart, registerables } from 'chart.js';
Chart.register(...registerables);

const InvoiceGraph = ({ data }) => {
  const [chartData, setChartData] = useState({ datasets: [] });

  useEffect(() => {
    if (!data || data.length === 0) {
      setChartData({ datasets: [] });
      return;
    }

    const processedData = processChartData(data);

    const isDarkMode = document.documentElement.classList.contains('dark');
    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');

    // Create gradients for each dataset
    const paidGradient = ctx.createLinearGradient(0, 0, 0, 400);
    paidGradient.addColorStop(0, 'rgba(16, 185, 129, 0.2)');
    paidGradient.addColorStop(1, 'rgba(16, 185, 129, 0)');

    const pendingGradient = ctx.createLinearGradient(0, 0, 0, 400);
    pendingGradient.addColorStop(0, 'rgba(245, 158, 11, 0.2)');
    pendingGradient.addColorStop(1, 'rgba(245, 158, 11, 0)');

    const lossGradient = ctx.createLinearGradient(0, 0, 0, 400);
    lossGradient.addColorStop(0, 'rgba(239, 68, 68, 0.2)');
    lossGradient.addColorStop(1, 'rgba(239, 68, 68, 0)');

    setChartData({
      labels: processedData.labels,
      datasets: [
        {
          label: 'Paid',
          data: processedData.paid,
          borderColor: '#10b981',
          backgroundColor: paidGradient,
          borderWidth: 3,
          pointBackgroundColor: '#ffffff',
          pointBorderColor: '#10b981',
          pointBorderWidth: 2,
          pointRadius: 4,
          pointHoverRadius: 6,
          tension: 0.4,
          fill: true,
        },
        {
          label: 'Pending',
          data: processedData.pending,
          borderColor: '#f59e0b',
          backgroundColor: pendingGradient,
          borderWidth: 3,
          borderDash: [5, 5],
          pointBackgroundColor: '#ffffff',
          pointBorderColor: '#f59e0b',
          pointBorderWidth: 2,
          pointRadius: 4,
          pointHoverRadius: 6,
          tension: 0.4,
          fill: true,
        },
        {
          label: 'Loss',
          data: processedData.loss,
          borderColor: '#ef4444',
          backgroundColor: lossGradient,
          borderWidth: 3,
          pointBackgroundColor: '#ffffff',
          pointBorderColor: '#ef4444',
          pointBorderWidth: 2,
          pointRadius: 4,
          pointHoverRadius: 6,
          tension: 0.4,
          fill: true,
        },
      ],
    });
  }, [data]);

  const processChartData = (invoices) => {
    // Group invoices by month
    const monthlyData = {};

    invoices.forEach(invoice => {
      // Use invoice_date (or another date field) to group by month
      const date = new Date(invoice.invoice_date || invoice.created_at);
      const monthKey = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
      const monthLabel = date.toLocaleDateString('en-US', { month: 'short', year: 'numeric' });

      if (!monthlyData[monthKey]) {
        monthlyData[monthKey] = {
          label: monthLabel,
          paid: 0,
          pending: 0,
          loss: 0,
          sortKey: monthKey,
        };
      }

      // Calculate total invoice amount (base_price + qst + gst)
      const totalAmount = parseFloat(invoice.base_price || 0) +
                         parseFloat(invoice.qst || 0) +
                         parseFloat(invoice.gst || 0);

      // Add to appropriate status
      const status = (invoice.payment_status || 'pending').toLowerCase();
      if (status === 'paid') {
        monthlyData[monthKey].paid += totalAmount;
      } else if (status === 'pending') {
        monthlyData[monthKey].pending += totalAmount;
      } else if (status === 'loss') {
        monthlyData[monthKey].loss += totalAmount;
      }
    });

    // Sort by month chronologically
    const sortedMonths = Object.keys(monthlyData).sort();

    const labels = [];
    const paid = [];
    const pending = [];
    const loss = [];

    sortedMonths.forEach(monthKey => {
      const monthData = monthlyData[monthKey];
      labels.push(monthData.label);
      paid.push(monthData.paid);
      pending.push(monthData.pending);
      loss.push(monthData.loss);
    });

    return { labels, paid, pending, loss };
  };

  const options = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        display: true,
        position: 'top',
        align: 'end',
        labels: {
          usePointStyle: true,
          pointStyle: 'circle',
          padding: 15,
          color: document.documentElement.classList.contains('dark') ? '#9ca3af' : '#6b7280',
          font: {
            family: 'Inter',
            size: 12,
          },
        },
      },
      tooltip: {
        backgroundColor: '#1f2937',
        titleColor: '#fff',
        bodyColor: '#fff',
        padding: 12,
        cornerRadius: 8,
        displayColors: true,
        usePointStyle: true,
        callbacks: {
          label: function(context) {
            let label = context.dataset.label || '';
            if (label) {
              label += ': ';
            }
            if (context.parsed.y !== null) {
              label += '$' + context.parsed.y.toFixed(2);
            }
            return label;
          }
        },
      },
    },
    scales: {
      y: {
        beginAtZero: true,
        grid: {
          color: document.documentElement.classList.contains('dark')
            ? 'rgba(255, 255, 255, 0.1)'
            : 'rgba(0, 0, 0, 0.05)',
          drawBorder: false,
        },
        ticks: {
          color: document.documentElement.classList.contains('dark') ? '#9ca3af' : '#6b7280',
          font: {
            family: 'Inter',
          },
          callback: function (value) {
            return '$' + value.toLocaleString();
          },
        },
      },
      x: {
        grid: {
          display: false,
        },
        ticks: {
          color: document.documentElement.classList.contains('dark') ? '#9ca3af' : '#6b7280',
          font: {
            family: 'Inter',
          },
        },
      },
    },
  };

  return (
    <div className="w-full h-full p-6">
      <div className="relative h-full w-full">
        {data && data.length > 0 ? (
          <Line data={chartData} options={options} />
        ) : (
          <div className="flex items-center justify-center h-full">
            <p className="text-gray-500 dark:text-gray-400">No invoice data to display</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default InvoiceGraph;
